window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7c3e8bf6e850e865"]={"versions": [{"id": "FIG-7c3e8bf6e850e865", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Master-Ablaufs der CAN-Zeitsynchronisation (AUTOSAR Classic Platform, BSW-Modul CanTSyn). Das Diagramm spezifiziert das zweistufige Synchronisationsverfahren (2-Step Time Master mit SYNC- und FUP-Botschaften) im Zusammenspiel zwischen dem Synchronized Time-Base Manager (StbM), dem CAN Time Synchronization Modul (CanTSyn) und dem CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Lebenslinien / BSW-Module:</strong></p>\n<ul class=\"fig-list\">\n<li><code>«module» StbM</code>: Verwaltet die synchronisierte Zeitbasis sowie die Virtual Local Time (VLT).</li>\n<li><code>«module» CanTSyn</code>: Steuert als Time Master die Generierung von SYNC- und FUP-Nachrichten sowie die Zeitstempelberechnung.</li>\n<li><code>«module» CanIf</code>: CAN Interface zur Botschaftsübertragung und Bereitstellung der Tx-Bestätigung.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen & Aufrufe:</strong></p>\n<ul class=\"fig-list\">\n<li><code>CanTSyn_MainFunction()</code>: Periodische Hauptfunktion des Moduls CanTSyn.</li>\n<li><code>StbM_BusGetCurrentTime(Std_ReturnType, StbM_SynchronizedTimeBaseType, StbM_TimeStampType<em>, StbM_VirtualLocalTimeType</em>, StbM_UserDataType*)</code>: Synchroner Abruf der aktuellen globalen Zeit (<code>globalTimePtr</code>), der zugehörigen lokalen Zeit (<code>localTimePtr</code>) und Anwenderdaten.</li>\n<li><code>CanIf_Transmit(SYNC)</code> / <code>CanIf_Transmit(FUP)</code>: Sendeaufrufe an CanIf für SYNC- und Follow-Up-PDUs.</li>\n<li><code>CanTSyn_TxConfirmation(SYNC)</code>: Callback von CanIf an CanTSyn nach erfolgreichem Senden des SYNC-Frames.</li>\n<li><code>StbM_GetCurrentVirtualLocalTime(StbM_SynchronizedTimeBaseType, StbM_VirtualLocalTimeType*): Std_ReturnType</code>: Synchroner Abruf der exakten virtuellen lokalen Zeit im Kontext der TxConfirmation.</li>\n</ul>\n<p class=\"fig-p\"><strong>Parameter & interne Variablen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>T0SYNCns</code>: Nanosekundenanteil von <code>*globalTimePtr</code> zum Abtastzeitpunkt T0.</li>\n<li><code>T0VLT</code>: Lokale Referenzzeit <code>*localTimePtr</code> zum Zeitpunkt T0.</li>\n<li><code>T1VLT</code>: Lokale Zeit <code>*localTimePtr</code> zum Sendezeitpunkt T1.</li>\n<li><code>T4</code>: Berechneter Sendezeitpunkt $T4 = T0SYNCns + (T1VLT - T0VLT)$.</li>\n<li><code>OVS</code>: Sekundenüberlauf (<code>second portion of T4</code>), bedingt durch <code>[T4 &gt;= 1s]</code>.</li>\n<li><code>SyncTimeNSec</code>: Nanosekundenanteil von $T4$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>SYNC-Initiierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>CanTSyn_MainFunction()</code> fragt CanTSyn über <code>StbM_BusGetCurrentTime(...)</code> die Zeitbasis ab und speichert intern <code>T0SYNCns</code> sowie <code>T0VLT</code>.</li>\n<li>CanTSyn stößt via <code>CanIf_Transmit(SYNC)</code> das Senden der Synchronisationsbotschaft an.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Sendezeitpunkterfassung via TxConfirmation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Bustransfer ruft CanIf den Callback <code>CanTSyn_TxConfirmation(SYNC)</code> auf.</li>\n<li>CanTSyn ruft sofort <code>StbM_GetCurrentVirtualLocalTime(...)</code> auf und belegt <code>T1VLT</code>.</li>\n<li>CanTSyn berechnet $T4 = T0SYNCns + (T1VLT - T0VLT)$. Falls $T4 \\ge 1\\,\\text{s}$, wird der Sekundenübertrag in <code>OVS</code> abgelegt; <code>SyncTimeNSec</code> erhält den verbleibenden Nanosekundenanteil.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Follow-Up-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Im nachfolgenden Aufruf von <code>CanTSyn_MainFunction()</code> wird per <code>CanIf_Transmit(FUP)</code> die Follow-Up-Botschaft mit den berechneten Zeitdaten (<code>SyncTimeNSec</code>, ggf. <code>OVS</code>) abgesetzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Latenz- und Jitterminimierung (Hinweisbox):</strong></li>\n<li><code>StbM_GetCurrentVirtualLocalTime()</code> muss zur Minimierung von Messfehlern so früh wie möglich in <code>CanTSyn_TxConfirmation()</code> aufgerufen werden.</li>\n<li>Das System muss Unterbrechungen vom Beginn der TxIndication/TxConfirmation bis zur Rückkehr von <code>StbM_GetCurrentVirtualLocalTime()</code> unterbinden (kritischer Abschnitt).</li>\n<li><strong>2-Step-Synchronisationsprinzip:</strong> Rechnerischer Ausgleich von Sende- und Busarbitrierungsverzögerungen über die nachgelagerte FUP-Nachricht, da Standard-CAN-Hardware keine Sendezeitstempel direkt im SYNC-Frame injizieren kann.</li>\n</ul>"}, {"id": "FIG-523402c869503923", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Master-Ablaufs der CAN-Zeitsynchronisation (AUTOSAR Classic Platform, BSW-Modul CanTSyn). Das Diagramm spezifiziert das zweistufige Synchronisationsverfahren (2-Step Time Master mit SYNC- und FUP-Botschaften) im Zusammenspiel zwischen dem Synchronized Time-Base Manager (StbM), dem CAN Time Synchronization Modul (CanTSyn) und dem CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Lebenslinien / BSW-Module:</strong></p>\n<ul class=\"fig-list\">\n<li><code>«module» StbM</code>: Verwaltet Zeitbasen, Virtual Local Time und verarbeitet Master-Timing-Messdaten.</li>\n<li><code>«module» CanTSyn</code>: Time Master, steuert SYNC/FUP-Protokoll, Zeitstempelkorrektur und Validierungsdatenerfassung.</li>\n<li><code>«module» CanIf</code>: CAN Interface zur Übertragungsabwicklung.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen & Aufrufe:</strong></p>\n<ul class=\"fig-list\">\n<li><code>CanTSyn_MainFunction()</code>: Periodische Hauptfunktion von CanTSyn.</li>\n<li><code>StbM_BusGetCurrentTime(Std_ReturnType, StbM_SynchronizedTimeBaseType, StbM_TimeStampType<em>, StbM_VirtualLocalTimeType</em>, StbM_UserDataType*)</code>: Synchroner Abruf von Zeitbasis, VLT und User Data.</li>\n<li><code>CanIf_Transmit(SYNC)</code> / <code>CanIf_Transmit(FUP)</code>: Sendeaufrufe für SYNC- und FUP-Frames.</li>\n<li><code>CanTSyn_TxConfirmation(SYNC)</code>: Sendeerfolgs-Callback von CanIf.</li>\n<li><code>StbM_GetCurrentVirtualLocalTime(StbM_SynchronizedTimeBaseType, StbM_VirtualLocalTimeType*): Std_ReturnType</code>: Synchroner VLT-Abruf in der TxConfirmation.</li>\n<li><code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code>: Synchroner API-Aufruf zur Übergabe der Messdaten an StbM.</li>\n</ul>\n<p class=\"fig-p\"><strong>Parameter, Datenstrukturen & Variablen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>T0SYNC</code>: Vollständiger globaler Zeitstempel <code>*globalTimePtr</code> zum Abtastzeitpunkt T0.</li>\n<li><code>T0SYNCns</code>: Nanosekundenanteil von <code>*globalTimePtr</code>.</li>\n<li><code>T0VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Zeitpunkt T0.</li>\n<li><code>T1VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Sendezeitpunkt T1.</li>\n<li><code>T4</code>: Korrigierter Sendezeitpunkt $T4 = T0SYNCns + (T1VLT - T0VLT)$.</li>\n<li><code>OVS</code>: Sekundenüberlauf (<code>second portion of T4</code>), bedingt durch <code>[T4 &gt;= 1s]</code>.</li>\n<li><code>SyncTimeNSec</code>: Nanosekundenanteil von $T4$.</li>\n<li><code>measurementData</code>: Struktur <code>{sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> für Time Validation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>SYNC-Initiierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>CanTSyn_MainFunction()</code> fragt CanTSyn über <code>StbM_BusGetCurrentTime(...)</code> die Zeitbasis ab und speichert <code>T0SYNC</code> (<code>*globalTimePtr</code>), <code>T0SYNCns</code> sowie <code>T0VLT</code>.</li>\n<li>CanTSyn sendet den SYNC-Frame über <code>CanIf_Transmit(SYNC)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Sendezeitpunkterfassung via TxConfirmation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>CanIf ruft <code>CanTSyn_TxConfirmation(SYNC)</code> auf.</li>\n<li>CanTSyn liest unverzüglich via <code>StbM_GetCurrentVirtualLocalTime(...)</code> den Wert <code>T1VLT</code> aus.</li>\n<li>Berechnung von $T4 = T0SYNCns + (T1VLT - T0VLT)$, <code>OVS</code> (bei $T4 \\ge 1\\,\\text{s}$) und <code>SyncTimeNSec</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>FUP-Übertragung & Time Validation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Im folgenden Zyklus von <code>CanTSyn_MainFunction()</code> wird <code>CanIf_Transmit(FUP)</code> aufgerufen.</li>\n<li><strong>Kombiniertes Fragment <code>opt [Time Validation enabled]</code>:</strong></li>\n<li>Bei aktivierter Zeitvalidierung bereitet CanTSyn <code>measurementData = {sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> vor.</li>\n<li>Aufruf von <code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code> zur synchronen Weitergabe der Messdaten an StbM.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Latenz- und Jitterminimierung (Hinweisbox):</strong></li>\n<li><code>StbM_GetCurrentVirtualLocalTime()</code> muss so früh wie möglich in <code>CanTSyn_TxConfirmation()</code> ausgeführt werden.</li>\n<li>Unterbrechungen zwischen Beginn der TxIndication/TxConfirmation und Ende der VLT-Abfrage sind zwingend zu sperren.</li>\n<li><strong>2-Step-Synchronisationsprinzip:</strong> Kompensation variabler Buszugriffsverzögerungen über den nachfolgenden FUP-Frame.</li>\n<li><strong>Time Validation Unterstützung:</strong></li>\n<li>Bei aktiver Validierungskonfiguration (<code>[Time Validation enabled]</code>) müssen die Master-Timing-Messdaten (Sequenzzähler, Sendezeitpunkt T1VLT und errechneter absoluter globaler Sendezeitstempel) erfasst und via <code>StbM_CanSetMasterTimingData</code> an StbM gemeldet werden.</li>\n<li>Die Messdatenübergabe erfolgt synchron im Kontext von <code>CanTSyn_MainFunction()</code> unmittelbar nach Anstoßen der FUP-Übertragung.</li>\n</ul>"}, {"id": "FIG-195cb4f037462b7c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Master-Ablaufs der CAN-Zeitsynchronisation (AUTOSAR Classic Platform, BSW-Modul CanTSyn). Das Diagramm spezifiziert das zweistufige Synchronisationsverfahren (2-Step Time Master mit SYNC- und FUP-Botschaften) im Zusammenspiel zwischen dem Synchronized Time-Base Manager (StbM), dem CAN Time Synchronization Modul (CanTSyn) und dem CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Lebenslinien / BSW-Module:</strong></p>\n<ul class=\"fig-list\">\n<li><code>«module» StbM</code>: Verwaltet Zeitbasen, Virtual Local Time und verarbeitet Master-Timing-Messdaten.</li>\n<li><code>«module» CanTSyn</code>: Time Master, steuert SYNC/FUP-Protokoll, Zeitstempelkorrektur und Validierungsdatenerfassung.</li>\n<li><code>«module» CanIf</code>: CAN Interface zur Übertragungsabwicklung.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen & Aufrufe:</strong></p>\n<ul class=\"fig-list\">\n<li><code>CanTSyn_MainFunction()</code>: Periodische Hauptfunktion von CanTSyn.</li>\n<li><code>StbM_BusGetCurrentTime(Std_ReturnType, StbM_SynchronizedTimeBaseType, StbM_TimeStampType<em>, StbM_VirtualLocalTimeType</em>, StbM_UserDataType*)</code>: Synchroner Abruf von Zeitbasis, VLT und User Data.</li>\n<li><code>CanIf_Transmit(SYNC)</code> / <code>CanIf_Transmit(FUP)</code>: Sendeaufrufe für SYNC- und FUP-Frames.</li>\n<li><code>CanTSyn_TxConfirmation(SYNC)</code>: Sendeerfolgs-Callback von CanIf.</li>\n<li><code>StbM_GetCurrentVirtualLocalTime(StbM_SynchronizedTimeBaseType, StbM_VirtualLocalTimeType*): Std_ReturnType</code>: Synchroner VLT-Abruf in der TxConfirmation.</li>\n<li><code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code>: Synchroner API-Aufruf zur Übergabe der Messdaten an StbM.</li>\n</ul>\n<p class=\"fig-p\"><strong>Parameter, Datenstrukturen & Variablen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>T0SYNC</code>: Vollständiger globaler Zeitstempel <code>*globalTimePtr</code> zum Abtastzeitpunkt T0.</li>\n<li><code>T0SYNCns</code>: Nanosekundenanteil von <code>*globalTimePtr</code>.</li>\n<li><code>T0VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Zeitpunkt T0.</li>\n<li><code>T1VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Sendezeitpunkt T1.</li>\n<li><code>T4</code>: Korrigierter Sendezeitpunkt $T4 = T0SYNCns + (T1VLT - T0VLT)$.</li>\n<li><code>OVS</code>: Sekundenüberlauf (<code>second portion of T4</code>), bedingt durch <code>[T4 &gt;= 1s]</code>.</li>\n<li><code>SyncTimeNSec</code>: Nanosekundenanteil von $T4$.</li>\n<li><code>measurementData</code>: Struktur <code>{sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> für Time Validation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>SYNC-Initiierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>CanTSyn_MainFunction()</code> fragt CanTSyn über <code>StbM_BusGetCurrentTime(...)</code> die Zeitbasis ab und speichert <code>T0SYNC</code> (<code>*globalTimePtr</code>), <code>T0SYNCns</code> sowie <code>T0VLT</code>.</li>\n<li>CanTSyn sendet den SYNC-Frame über <code>CanIf_Transmit(SYNC)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Sendezeitpunkterfassung via TxConfirmation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>CanIf ruft <code>CanTSyn_TxConfirmation(SYNC)</code> auf.</li>\n<li>CanTSyn liest unverzüglich via <code>StbM_GetCurrentVirtualLocalTime(...)</code> den Wert <code>T1VLT</code> aus.</li>\n<li>Berechnung von $T4 = T0SYNCns + (T1VLT - T0VLT)$, <code>OVS</code> (bei $T4 \\ge 1\\,\\text{s}$) und <code>SyncTimeNSec</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>FUP-Übertragung & Time Validation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Im folgenden Zyklus von <code>CanTSyn_MainFunction()</code> wird <code>CanIf_Transmit(FUP)</code> aufgerufen.</li>\n<li><strong>Kombiniertes Fragment <code>opt [Time Validation enabled]</code>:</strong></li>\n<li>Bei aktivierter Zeitvalidierung bereitet CanTSyn <code>measurementData = {sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> vor.</li>\n<li>Aufruf von <code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code> zur synchronen Weitergabe der Messdaten an StbM.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Latenz- und Jitterminimierung (Hinweisbox):</strong></li>\n<li><code>StbM_GetCurrentVirtualLocalTime()</code> muss so früh wie möglich in <code>CanTSyn_TxConfirmation()</code> ausgeführt werden.</li>\n<li>Unterbrechungen zwischen Beginn der TxIndication/TxConfirmation und Ende der VLT-Abfrage sind zwingend zu sperren.</li>\n<li><strong>2-Step-Synchronisationsprinzip:</strong> Kompensation variabler Buszugriffsverzögerungen über den nachfolgenden FUP-Frame.</li>\n<li><strong>Time Validation Unterstützung:</strong></li>\n<li>Bei aktiver Validierungskonfiguration (<code>[Time Validation enabled]</code>) müssen die Master-Timing-Messdaten (Sequenzzähler, Sendezeitpunkt T1VLT und errechneter absoluter globaler Sendezeitstempel) erfasst und via <code>StbM_CanSetMasterTimingData</code> an StbM gemeldet werden.</li>\n<li>Die Messdatenübergabe erfolgt synchron im Kontext von <code>CanTSyn_MainFunction()</code> unmittelbar nach Anstoßen der FUP-Übertragung.</li>\n</ul>"}], "trans": [{"from": "FIG-7c3e8bf6e850e865", "to": "FIG-523402c869503923", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung des Interaktionsfragments <code>opt [Time Validation enabled]</code> am Ende des Ablaufs in <code>CanTSyn_MainFunction()</code>.</li>\n<li>Neuer synchroner API-Aufruf <code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code> von <code>CanTSyn</code> an <code>StbM</code>.</li>\n<li>Einführung der Datenstruktur <code>measurementData = {sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> in <code>CanTSyn</code>.</li>\n<li>Erweiterung der internen Variablenbelegung nach <code>StbM_BusGetCurrentTime</code>: Speicherung von <code>T0SYNC = *globalTimePtr</code> zusätzlich zu <code>T0SYNCns</code>.</li>\n</ul>"}, {"from": "FIG-523402c869503923", "to": "FIG-195cb4f037462b7c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
